WITH enriched AS (SELECT id, carrier, delivered_date, status, LAST_VALUE(cost, TRUE) OVER (PARTITION BY order_id ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_cost, LAG(cost, 1) OVER (PARTITION BY carrier ORDER BY cost, id) prev_cost, ROW_NUMBER() OVER (PARTITION BY carrier ORDER BY shipped_date DESC, id) row_seq FROM shipments) SELECT id, carrier, delivered_date, status, last_known_cost, row_seq FROM enriched ORDER BY carrier NULLS FIRST, status
